187|		await runTinyWorker();
188|		return true;
189|	}
190|	if (arg === STATS_SYNC_WORKER_ARG) {
191|		// The sync worker handles messages via `self.onmessage`, assigned during
192|		// this *async* dynamic import. Bun flushes the worker's initial message
193|		// buffer when the entry module's top-level evaluation finishes — before
194|		// this dispatch completes — so anything the parent posted right after
195|		// spawning (the smoke ping, the first parse request) would be dropped.
196|		// Park early events and replay them once the module's handler is live.
197|		// Worker-thread entries using `parentPort` need the same sync-prefix
198|		// buffering; the computer/tab/eval cases install that inbox below.
199|		const scope = globalThis as unknown as { onmessage: ((event: MessageEvent) => void) | null };
200|		const pending: MessageEvent[] = [];
201|		const buffer = (event: MessageEvent): void => {
202|			pending.push(event);
203|		};
204|		scope.onmessage = buffer;
205|		await import("@oh-my-pi/omp-stats/sync-worker");
206|		const handler = scope.onmessage;
207|		if (handler && handler !== buffer) {
208|			for (const event of pending) handler.call(scope, event);
