 * these still enters interactive mode, so the speculative first frame is
 * valid; anything else (subcommands, `-p`, model/session selectors) skips it.
 */
const PREPAINT_SAFE_FLAGS: Record<string, true> = {
	"--no-session": true,
	"--no-extensions": true,
	"--no-skills": true,
	"--no-rules": true,
	"--no-tools": true,
	"--no-lsp": true,
	"--no-title": true,
	"--no-prewalk": true,
	"--no-pty": true,
};

