	await smokeTestComputerWorker();
	await smokeTestTtsWorker();
	await smokeTestMnemopiEmbedWorker();
	await smokeTestDaemonBroker();
	await smokeTestLspMux();
	await smokeTestBlobBroker();
	await smokeTestTerminalOutputWorker();
