1|/**
2| * Centralized path helpers for tau config directories.
3| *
4| * Uses PI_CONFIG_DIR (default ".tau") for the config root and
5| * PI_CODING_AGENT_DIR to override the agent directory.
6| *
7| * On Linux, if XDG_DATA_HOME / XDG_STATE_HOME / XDG_CACHE_HOME environment
8| * variables are set, paths are redirected to XDG-compliant locations under
9| * $XDG_*_HOME/tau/. This requires running `tau config migrate` first to
10| * move data to the new locations. No filesystem existence checks are performed
11| * — if the env var is set, omp trusts that the migration has been done.
12| */
13|
14|import * as fs from "node:fs";
15|import * as os from "node:os";
16|import * as path from "node:path";
17|import { engines, version } from "../package.json" with { type: "json" };
18|import { isEnoent, isEnotdir } from "./fs-error";
19|
20|/** App name (e.g. "tau") */
21|export const APP_NAME: string = "tau";
22|
23|/** Config directory name (e.g. ".tau") */
24|export const CONFIG_DIR_NAME: string = ".tau";
25|
26|/** Ordered main settings filenames: canonical write target first, legacy-compatible YAML fallback second. */
27|export const MAIN_CONFIG_FILENAMES = ["config.yml", "config.yaml"] as const;
28|
29|/** Version (e.g. "1.0.0") */
30|export const VERSION: string = version;
31|
32|/** Default User-Agent header string (e.g. "omp/17.2.12") */
33|export const USER_AGENT = `omp/${VERSION}`;
34|
35|/** Minimum Bun version */
36|export const MIN_BUN_VERSION: string = engines.bun.replace(/[^0-9.]/g, "");
37|
38|const PROFILE_NAME_RE = /^[a-z0-9][a-z0-9._-]{0,63}$/;
39|const PROFILE_ENV_KEYS = ["OMP_PROFILE", "PI_PROFILE"] as const;
40|
41|/**
42| * Names Windows treats as reserved device aliases. Matches the basename
43| * itself as well as any `BASENAME.<anything>` form, because Windows reserves
44| * `CON.foo`/`PRN.txt`/etc. too — using them as a profile name would let
45| * `setProfile` accept the input only for directory creation to fail later
46| * with a confusing `ENOENT`/`EINVAL`. Case-insensitive: NTFS treats `CON`
47| * and `con` identically.
48| */
49|const WINDOWS_RESERVED_BASENAME_RE = /^(?:CON|PRN|AUX|NUL|COM[0-9]|LPT[0-9])(?:\..*)?$/i;
50|
51|/**
52| * Normalize and validate a profile name. Returns `undefined` for the implicit
53| * default (empty string, whitespace, or the explicit "default" sentinel) and
54| * throws for syntactically invalid or platform-reserved names.
55| *
56| * Exported so consumers of `@oh-my-pi/pi-utils/dirs` (CLI bootstrap, tests,
57| * downstream tools) can validate user input without re-deriving the rules.
58| */
59|export function normalizeProfileName(profile: string | undefined): string | undefined {
60|	const normalized = profile?.trim();
61|	if (!normalized || normalized === "default") return undefined;
62|	if (
63|		normalized === "." ||
64|		normalized === ".." ||
65|		normalized.endsWith(".") ||
66|		!PROFILE_NAME_RE.test(normalized) ||
67|		WINDOWS_RESERVED_BASENAME_RE.test(normalized)
68|	) {
69|		throw new Error(
70|			`Invalid OMP profile "${profile}". Profile names must match ${PROFILE_NAME_RE.source}, ` +
71|				`cannot be "." or "..", cannot end with ".", and cannot be a Windows reserved device name ` +
72|				`(CON, PRN, AUX, NUL, COM0-9, LPT0-9, or any of those with an extension).`,
73|		);
74|	}
75|	return normalized;
76|}
77|
78|/**
79| * Resolve the active profile from the two profile env vars. `OMP_PROFILE` is the
80| * canonical variable and takes precedence; `PI_PROFILE` is the legacy
81| * compatibility fallback, consulted only when `OMP_PROFILE` is undefined. An
82| * explicitly-empty `OMP_PROFILE` therefore selects the default profile rather
83| * than silently inheriting `PI_PROFILE`. Delegates validation/normalization to
84| * {@link normalizeProfileName} (which throws on a syntactically invalid value).
85| */
86|export function resolveProfileEnv(omp: string | undefined, pi: string | undefined): string | undefined {
87|	return normalizeProfileName(omp !== undefined ? omp : pi);
88|}
89|
90|function getProfileFromEnv(): string | undefined {
91|	return resolveProfileEnv(process.env.OMP_PROFILE, process.env.PI_PROFILE);
92|}
93|
94|/**
95| * Module-load profile resolution. Unlike {@link getProfileFromEnv}, an invalid
96| * OMP_PROFILE/PI_PROFILE value does NOT throw here — a bad env var must not
97| * crash a bare `import` of this module with an uncaught stack trace before the
98| * CLI's error handling is in scope. The default profile is used instead; the
99| * CLI re-validates the env (see `runCli` in coding-agent/src/cli.ts) so the
100| * user still gets a clean "Invalid OMP profile" message.
101| */
102|function readProfileFromEnvSafe(): string | undefined {
103|	try {
104|		return getProfileFromEnv();
105|	} catch {
106|		return undefined;
107|	}
108|}
109|
110|/** Profile-independent config root (~/.omp), shared by every omp profile. */
111|export function getBaseConfigRoot(): string {
112|	return path.join(os.homedir(), getConfigDirName());
113|}
114|
115|function getProfileConfigRoot(profile: string | undefined): string {
116|	const root = getBaseConfigRoot();
117|	return profile ? path.join(root, "profiles", profile) : root;
118|}
119|
120|function readPiProfileFromEnvSafe(): string | undefined {
121|	try {
122|		return normalizeProfileName(process.env.PI_PROFILE);
123|	} catch {
124|		return undefined;
125|	}
126|}
127|
128|function getProfileAgentDir(profile: string): string {
129|	return path.join(getProfileConfigRoot(profile), "agent");
130|}
131|
132|function isProfileDerivedAgentDir(profile: string | undefined, agentDirEnv: string | undefined): boolean {
133|	return profile !== undefined && agentDirEnv === getProfileAgentDir(profile);
134|}
135|// =============================================================================
136|// Project directory
137|// =============================================================================
138|
139|/**
140| * On macOS, strip /private prefix only when both paths resolve to the same location.
141| * This preserves aliases like /private/tmp -> /tmp without rewriting unrelated paths.
142| */
143|function standardizeMacOSPath(p: string): string {
144|	if (process.platform !== "darwin" || !p.startsWith("/private/")) return p;
145|	const stripped = p.slice("/private".length);
146|	try {
147|		if (fs.realpathSync(p) === fs.realpathSync(stripped)) {
148|			return stripped;
149|		}
150|	} catch {}
151|	return p;
152|}
153|
154|export function resolveEquivalentPath(inputPath: string): string {
155|	const resolvedPath = path.resolve(inputPath);
156|	try {
157|		return fs.realpathSync(resolvedPath);
158|	} catch {
159|		return resolvedPath;
160|	}
161|}
162|
163|export function normalizePathForComparison(inputPath: string): string {
164|	const resolvedPath = resolveEquivalentPath(inputPath);
165|	return process.platform === "win32" ? resolvedPath.toLowerCase() : resolvedPath;
166|}
167|
168|/**
169| * Compare paths already normalized by {@link normalizePathForComparison}.
170| *
171| * Returns the relative path (an empty string when the paths are equal), or
172| * `null` when the candidate is outside the root. Callers classifying one
173| * candidate against several static roots can normalize each side once and
174| * reuse the public helpers' containment semantics without repeating realpath
175| * work.
176| */
177|export function relativePathWithinNormalizedRoot(normalizedRoot: string, normalizedCandidate: string): string | null {
178|	const relative = path.relative(normalizedRoot, normalizedCandidate);
179|	if (relative !== "" && (relative.startsWith("..") || path.isAbsolute(relative))) return null;
180|	return relative;
181|}
182|
183|export function pathIsWithin(root: string, candidate: string): boolean {
184|	const normalizedRoot = normalizePathForComparison(root);
185|	const normalizedCandidate = normalizePathForComparison(candidate);
186|	return relativePathWithinNormalizedRoot(normalizedRoot, normalizedCandidate) !== null;
187|}
188|
189|export function relativePathWithinRoot(root: string, candidate: string): string | null {
190|	const normalizedRoot = normalizePathForComparison(root);
191|	const normalizedCandidate = normalizePathForComparison(candidate);
192|	return relativePathWithinNormalizedRoot(normalizedRoot, normalizedCandidate) || null;
193|}
194|
195|let projectDir: string | undefined;
196|
197|/** Get the project directory. */
198|export function getProjectDir(): string {
199|	if (projectDir === undefined) {
200|		try {
201|			projectDir = standardizeMacOSPath(process.cwd());
202|		} catch {
203|			const candidates = [process.env.PWD, os.homedir(), os.tmpdir()];
204|			for (const candidate of candidates) {
205|				if (!candidate || !path.isAbsolute(candidate)) continue;
206|				try {
207|					process.chdir(candidate);
208|					projectDir = standardizeMacOSPath(candidate);
209|					break;
210|				} catch {}
211|			}
212|			if (projectDir === undefined) {
213|				throw new Error("Unable to determine an accessible working directory");
214|			}
215|		}
216|	}
217|	return projectDir;
218|}
219|
220|/** Set the project directory. */
221|export function setProjectDir(dir: string): void {
222|	const resolved = standardizeMacOSPath(path.resolve(dir));
223|	process.chdir(resolved);
224|	projectDir = resolved;
225|}
226|
227|/** Reset the cached project directory (test seam). */
228|export function __resetProjectDirCacheForTests(): void {
229|	projectDir = undefined;
230|}
231|
232|/** Whether a path is absent or not a directory. Other stat failures return false. */
233|export async function directoryIsMissing(dir: string): Promise<boolean> {
234|	try {
235|		return !(await fs.promises.stat(dir)).isDirectory();
236|	} catch (error) {
237|		return isEnoent(error) || isEnotdir(error);
238|	}
239|}
240|
241|/**
242| * Whether `dir` resolves to an existing directory. Any stat failure — a deleted
243| * path (ENOENT), permission error, or a non-directory — returns `false`, so
244| * callers can decide whether a directory is safe to `chdir` into or adopt as a
245| * working directory before {@link setProjectDir} throws on it.
246| */
247|export async function directoryExists(dir: string): Promise<boolean> {
248|	try {
249|		return (await fs.promises.stat(dir)).isDirectory();
250|	} catch {
251|		return false;
252|	}
253|}
254|
255|/**
256| * Whether `dir` both exists and can be entered. POSIX `stat` succeeds for a
257| * directory whose own search/execute permission is denied (it only needs
258| * +x on the parent chain), so existence alone does not imply `chdir` works.
259| * Callers that adopt a directory as a working directory must check this
260| * rather than {@link directoryExists} alone.
261| */
262|export async function directoryIsEnterable(dir: string): Promise<boolean> {
263|	try {
264|		const [stats] = await Promise.all([fs.promises.stat(dir), fs.promises.access(dir, fs.constants.X_OK)]);
265|		return stats.isDirectory();
266|	} catch {
267|		return false;
268|	}
269|}
270|
271|/** Whether `dir` is enterable, synchronous variant. See {@link directoryIsEnterable}. */
272|export function directoryIsEnterableSync(dir: string): boolean {
273|	try {
274|		fs.accessSync(dir, fs.constants.X_OK);
275|		return fs.statSync(dir).isDirectory();
276|	} catch {
277|		return false;
278|	}
279|}
280|
281|/**
282| * Project directory when it is enterable, otherwise a safe fallback.
283| * Used by spawns that must preserve project-relative behavior when healthy.
284| */
285|export function getSafeProjectCwd(): string {
286|	try {
287|		const dir = getProjectDir();
288|		if (directoryIsEnterableSync(dir)) return dir;
289|	} catch {}
290|	return os.homedir();
291|}
292|
293|/** Get the config directory name relative to home (e.g. ".tau" or PI_CONFIG_DIR override). */
294|export function getConfigDirName(): string {
295|	return process.env.PI_CONFIG_DIR || CONFIG_DIR_NAME;
296|}
297|
298|/** Get the config agent directory name relative to home (e.g. ".omp/agent" or PI_CONFIG_DIR + "/agent"). */
299|export function getConfigAgentDirName(): string {
300|	const profile = getActiveProfile();
301|	return profile ? path.join(getConfigDirName(), "profiles", profile, "agent") : `${getConfigDirName()}/agent`;
302|}
303|
304|// =============================================================================
305|// DirResolver — cached, XDG-aware path resolution
306|// =============================================================================
307|
308|type XdgCategory = "data" | "state" | "cache";
309|
310|/**
311| * Resolves and caches all omp directory paths. On Linux, when XDG environment
312| * variables are set, paths are redirected under $XDG_*_HOME/tau/. A new
313| * instance is created whenever the agent directory changes, which naturally
314| * invalidates all cached paths.
315| */
316|class DirResolver {
317|	readonly configRoot: string;
318|	readonly agentDir: string;
319|
320|	// Per-category base dirs. Without XDG, all three equal configRoot / agentDir.
321|	// With XDG on Linux, they point to $XDG_*_HOME/tau/.
322|	readonly #rootDirs: Record<XdgCategory, string>;
