1|/**
2| * Centralized path helpers for tau config directories.
3| *
4| * Uses PI_CONFIG_DIR (default ".tau") for the config root and
5| * PI_CODING_AGENT_DIR to override the agent directory.
6| *
7| * On Linux, if XDG_DATA_HOME / XDG_STATE_HOME / XDG_CACHE_HOME environment
8| * variables are set, paths are redirected to XDG-compliant locations under
9| * $XDG_*_HOME/tau/. This requires running `tau config migrate` first to
10| * move data to the new locations. No filesystem existence checks are performed
11| * — if the env var is set, omp trusts that the migration has been done.
12| */
13|
14|import * as fs from "node:fs";
15|import * as os from "node:os";
16|import * as path from "node:path";
17|import { engines, version } from "../package.json" with { type: "json" };
18|import { isEnoent, isEnotdir } from "./fs-error";
19|
20|/** App name (e.g. "tau") */
21|export const APP_NAME: string = "tau";
22|
23|/** Config directory name (e.g. ".tau") */
24|export const CONFIG_DIR_NAME: string = ".tau";
25|
26|/** Ordered main settings filenames: canonical write target first, legacy-compatible YAML fallback second. */
27|export const MAIN_CONFIG_FILENAMES = ["config.yml", "config.yaml"] as const;
28|
29|/** Version (e.g. "1.0.0") */
30|export const VERSION: string = version;
31|
32|/** Default User-Agent header string (e.g. "omp/17.2.12") */
33|export const USER_AGENT = `omp/${VERSION}`;
34|
35|/** Minimum Bun version */
36|export const MIN_BUN_VERSION: string = engines.bun.replace(/[^0-9.]/g, "");
37|
38|const PROFILE_NAME_RE = /^[a-z0-9][a-z0-9._-]{0,63}$/;
39|const PROFILE_ENV_KEYS = ["OMP_PROFILE", "PI_PROFILE"] as const;
40|
41|/**
42| * Names Windows treats as reserved device aliases. Matches the basename
43| * itself as well as any `BASENAME.<anything>` form, because Windows reserves
44| * `CON.foo`/`PRN.txt`/etc. too — using them as a profile name would let
45| * `setProfile` accept the input only for directory creation to fail later
46| * with a confusing `ENOENT`/`EINVAL`. Case-insensitive: NTFS treats `CON`
47| * and `con` identically.
48| */
49|const WINDOWS_RESERVED_BASENAME_RE = /^(?:CON|PRN|AUX|NUL|COM[0-9]|LPT[0-9])(?:\..*)?$/i;
50|
51|/**
52| * Normalize and validate a profile name. Returns `undefined` for the implicit
53| * default (empty string, whitespace, or the explicit "default" sentinel) and
54| * throws for syntactically invalid or platform-reserved names.
55| *
