1|/**
2| * Minimal CLI framework — drop-in replacement for the subset of @oclif/core
3| * actually used by the coding agent. Provides `Command`, `Args`, `Flags`,
4| * and a `run()` entry point with explicit command registration.
5| *
6| * Design goals:
7| *   - Zero dependencies beyond node builtins
8| *   - No filesystem scanning, no manifest files, no plugin loading
9| *   - Lazy command imports (only the invoked command is loaded)
10| *   - Typed `this.parse()` output matching oclif's API shape
11| */
12|import * as fs from "node:fs";
13|import { parseArgs as nodeParseArgs } from "node:util";
14|
15|/**
16| * Streaming startup marker, enabled by `PI_DEBUG_STARTUP`. Local copy of
17| * `logger.startupMarker` so the minimal `--version`/bootstrap import graph
18| * stays free of the winston-backed logger module. Synchronous on purpose:
19| * a command module whose import hangs (dlopen, fs on a dead mount) must
20| * still leave its `:start` marker behind.
21| */
22|function startupMarker(text: string): void {
23|	if (!process.env.PI_DEBUG_STARTUP) return;
24|	try {
25|		fs.writeSync(2, `[startup] ${text}\n`);
26|	} catch {
27|		// stderr unavailable; markers are best-effort
28|	}
29|}
30|
31|/**
32| * A user-facing argument/flag validation failure. Thrown by {@link Command.parse}
33| * for missing/invalid positionals and flags. The top-level {@link run} handler
34| * prints its message plus the command usage line to stderr and exits 1, instead
35| * of letting it bubble to the process-level catch — which would dump a minified
36| * `dist/cli.js` code frame over a plain argument mistake (issue #5369).
37| */
38|export class CliUsageError extends Error {
39|	constructor(message: string) {
40|		super(message);
41|		this.name = "CliUsageError";
42|	}
43|}
44|
45|// ---------------------------------------------------------------------------
46|// Flag & Arg descriptors
47|// ---------------------------------------------------------------------------
48|
49|export interface FlagDescriptor<K extends "string" | "boolean" | "integer" = "string" | "boolean" | "integer"> {
50|	kind: K;
51|	description?: string;
52|	char?: string;
53|	default?: unknown;
54|	multiple?: boolean;
55|	options?: readonly string[];
56|	required?: boolean;
57|}
58|
59|export interface ArgDescriptor {
60|	kind: "string";
61|	description?: string;
62|	required?: boolean;
63|	multiple?: boolean;
64|	options?: readonly string[];
65|}
66|
67|interface FlagInput {
68|	description?: string;
69|	char?: string;
70|	default?: unknown;
71|	multiple?: boolean;
72|	options?: readonly string[];
73|	required?: boolean;
74|}
75|
76|interface ArgInput {
77|	description?: string;
78|	required?: boolean;
79|	multiple?: boolean;
80|	options?: readonly string[];
81|}
82|
83|/** Builders that match the `Flags.*()` / `Args.*()` API from oclif. */
84|export const Flags = {
85|	string<T extends FlagInput>(opts?: T): FlagDescriptor<"string"> & T {
86|		return { kind: "string" as const, ...opts } as FlagDescriptor<"string"> & T;
87|	},
88|	boolean<T extends FlagInput>(opts?: T): FlagDescriptor<"boolean"> & T {
89|		return { kind: "boolean" as const, ...opts } as FlagDescriptor<"boolean"> & T;
90|	},
91|	integer<T extends FlagInput & { default?: number }>(opts?: T): FlagDescriptor<"integer"> & T {
92|		return { kind: "integer" as const, ...opts } as FlagDescriptor<"integer"> & T;
93|	},
94|};
95|
96|export const Args = {
97|	string<T extends ArgInput>(opts?: T): ArgDescriptor & T {
98|		return { kind: "string" as const, ...opts } as ArgDescriptor & T;
99|	},
100|};
101|
102|// ---------------------------------------------------------------------------
103|// Parse result types — mirrors oclif's typed output from this.parse()
104|// ---------------------------------------------------------------------------
105|
106|type FlagValue<D extends FlagDescriptor> = D["kind"] extends "boolean"
107|	? D extends { default: boolean }
108|		? boolean
109|		: boolean | undefined
110|	: D["kind"] extends "integer"
111|		? D extends { default: number }
112|			? number
113|			: number | undefined
114|		: D extends { multiple: true }
115|			? string[] | undefined
116|			: string | undefined;
117|
118|type ArgValue<D extends ArgDescriptor> = D extends { multiple: true } ? string[] | undefined : string | undefined;
119|
120|type FlagValues<T extends Record<string, FlagDescriptor>> = { [K in keyof T]: FlagValue<T[K]> };
121|type ArgValues<T extends Record<string, ArgDescriptor>> = { [K in keyof T]: ArgValue<T[K]> };
122|
123|export interface ParseOutput<
124|	F extends Record<string, FlagDescriptor> = Record<string, FlagDescriptor>,
125|	A extends Record<string, ArgDescriptor> = Record<string, ArgDescriptor>,
126|> {
127|	flags: FlagValues<F>;
128|	args: ArgValues<A>;
129|	argv: string[];
130|}
131|
132|// ---------------------------------------------------------------------------
133|// Command base class
134|// ---------------------------------------------------------------------------
135|
136|export interface CommandMetadata {
137|	description?: string;
138|	hidden?: boolean;
139|	flags?: Record<string, FlagDescriptor>;
