148|}
149|
150|/** Configuration passed to every command instance and help renderers. */
151|export interface CliConfig<TCommand extends CommandMetadata = CommandCtor> {
152|	bin: string;
153|	version: string;
154|	/** All registered commands keyed by their canonical name. */
155|	commands: Map<string, TCommand>;
156|}
157|
158|/** Minimal Command base matching the oclif surface we use. */
159|export abstract class Command {
160|	argv: string[];
161|	config: CliConfig;
162|
163|	constructor(argv: string[], config: CliConfig) {
164|		this.argv = argv;
165|		this.config = config;
166|	}
167|
168|	abstract run(): Promise<void>;
169|
170|	/**
171|	 * Parse argv against the static `flags` and `args` declared on the
172|	 * concrete command class. Returns a typed `{ flags, args, argv }` object.
173|	 */
174|	async parse<C extends CommandCtor>(
175|		_Cmd: C,
176|	): Promise<
177|		ParseOutput<
178|			NonNullable<C["flags"]> extends Record<string, FlagDescriptor>
179|				? NonNullable<C["flags"]>
180|				: Record<string, FlagDescriptor>,
181|			NonNullable<C["args"]> extends Record<string, ArgDescriptor>
182|				? NonNullable<C["args"]>
183|				: Record<string, ArgDescriptor>
184|		>
185|	> {
186|		const Cmd = _Cmd as CommandCtor;
187|		const flagDefs = (Cmd.flags ?? {}) as Record<string, FlagDescriptor>;
188|		const argDefs = (Cmd.args ?? {}) as Record<string, ArgDescriptor>;
189|		const strict = Cmd.strict !== false;
190|
191|		// Build node:util parseArgs options from flag descriptors
192|		const options: Record<
193|			string,
194|			{ type: "string" | "boolean"; short?: string; multiple?: boolean; default?: string | boolean }
195|		> = {};
196|		for (const [name, desc] of Object.entries(flagDefs)) {
197|			const opt: (typeof options)[string] = {
198|				type: desc.kind === "boolean" ? "boolean" : "string",
199|			};
200|			if (desc.char) opt.short = desc.char;
201|			if (desc.multiple) opt.multiple = true;
202|			if (desc.default !== undefined) {
203|				opt.default = desc.kind === "boolean" ? Boolean(desc.default) : String(desc.default);
204|			}
205|			options[name] = opt;
206|		}
207|
208|		// strict=false when command declares args (positionals must pass through)
209|		// or when the command itself opts out
210|		const { values: rawValues, positionals } = (() => {
211|			try {
212|				return nodeParseArgs({
213|					args: this.argv,
214|					options,
215|					allowPositionals: true,
216|					strict,
217|				});
218|			} catch (error) {
219|				throw new CliUsageError(error instanceof Error ? error.message : String(error));
220|			}
221|		})();
222|
223|		// Convert raw values to proper types and validate
224|		const flags: Record<string, unknown> = {};
225|		for (const [name, desc] of Object.entries(flagDefs)) {
226|			const raw = rawValues[name];
227|			if (desc.kind === "integer") {
228|				if (raw === undefined || typeof raw === "boolean") {
229|					flags[name] = desc.default ?? undefined;
230|				} else {
