233|						throw new CliUsageError(`Expected integer for --${name}, got "${raw}"`);
234|					}
235|					flags[name] = n;
236|				}
237|			} else if (desc.kind === "boolean") {
238|				flags[name] =
239|					raw !== undefined ? Boolean(raw) : desc.default !== undefined ? Boolean(desc.default) : undefined;
240|			} else {
