244|				if (val !== undefined && desc.options && !Array.isArray(val)) {
245|					if (!desc.options.includes(val as string)) {
246|						throw new CliUsageError(
247|							`Expected --${name} to be one of: ${[...desc.options].join(", ")}; got "${val}"`,
248|						);
249|					}
250|				}
251|				flags[name] = val;
252|			}
253|			// Validate required
254|			if (desc.required && flags[name] === undefined) {
255|				throw new CliUsageError(`Missing required flag: --${name}`);
256|			}
257|		}
258|
259|		// Map positionals to named args in declaration order and validate
260|		const args: Record<string, unknown> = {};
261|		let posIdx = 0;
262|		for (const [argName, desc] of Object.entries(argDefs)) {
263|			if (desc.multiple) {
