265|				args[argName] = val.length > 0 ? val : undefined;
266|				posIdx = positionals.length;
267|			} else {
268|				const val = positionals[posIdx];
269|				args[argName] = val;
270|				posIdx++;
271|			}
272|			// Validate required
273|			if (desc.required && args[argName] === undefined) {
274|				throw new CliUsageError(`Missing required argument: ${argName}`);
275|			}
276|			// Validate options constraint
277|			const argVal = args[argName];
278|			if (argVal !== undefined && desc.options && typeof argVal === "string") {
279|				if (!desc.options.includes(argVal)) {
280|					throw new CliUsageError(
