295|/** Render full root help: header, default command details, subcommand list. */
296|export function renderRootHelp(config: CliConfig<CommandMetadata>): void {
297|	const { bin, version, commands } = config;
298|	const lines: string[] = [];
299|	lines.push(`${bin} v${version}\n`);
300|	lines.push("USAGE");
301|	lines.push(`  $ ${bin} [COMMAND]\n`);
302|
303|	// Show the default command's flags/args/examples inline.
304|	// The default command is the one marked hidden (it's the implicit entry point).
305|	const defaultCmd = [...commands.values()].find(command => command.hidden);
306|	if (defaultCmd) {
307|		renderCommandBody(lines, defaultCmd);
308|	}
309|
310|	// List visible subcommands
311|	const visible = [...commands.entries()].filter(([, C]) => !C.hidden);
312|	if (visible.length > 0) {
313|		lines.push("COMMANDS");
314|		const maxLen = Math.max(...visible.map(([n]) => n.length));
315|		for (const [name, command] of visible.sort((a, b) => a[0].localeCompare(b[0]))) {
316|			lines.push(`  ${name.padEnd(maxLen + 2)}${command.description ?? ""}`);
317|		}
318|		lines.push("");
319|	}
320|
321|	process.stdout.write(lines.join("\n"));
